async function resolveBundleFile(a) {
  const isFilePath =
    a.endsWith('.json') ||
    a.endsWith('.txt') ||
    a.startsWith('./') ||
    a.startsWith('../') ||
    a.startsWith('/') ||
    a.startsWith('~')
  if (isFilePath) {
    const resolvedPath = expandTilde(a, process.env.HOME || '/tmp')
    for (const candidate of [resolvedPath, join(process.cwd(), a)]) {
      try {
        await readFile(candidate, 'utf-8')
        return candidate
      } catch {}
    }
    throw new Error(`Bundle file not found: ${a}`)
  }

  const candidates = [
    a,
    join(process.cwd(), a),
    `${a}.json`,
    `${a}.txt`,
    join(process.cwd(), `${a}.json`),
    join(process.cwd(), `${a}.txt`),
  ]

  for (const candidate of candidates) {
    try {
      await readFile(candidate, 'utf-8')
      return candidate
    } catch {}
  }
  return null
}
